"""Puts the supplementary chart generated by the executed code back in the text without changing the existing data and formulae."""
from pathlib import Path
import shutil
import pandas as pd
from docx import Document
from build_research_report import add_figure, add_text

ROOT=Path(__file__).resolve().parent
CHARTS=ROOT/'report_work'/'visual_diagnostics'
REPORT=ROOT/'Study on Global Multi-Assessment Dynamic Strategies   Chinese.docx'


def main():
    backup=ROOT/'report_work'/'Study   Backup to Supplementary Mechanism Charts. Docx'
    if not backup.exists():
        shutil.copy2(REPORT,backup)
    # Repeated runs start with the same reviewed pre-insertion version.
    doc=Document(backup)
    body=doc._element.body

    def insert(anchor,items):
        target=next(p._p for p in doc.paragraphs if p.text.startswith(anchor))
        original=set(body)
        for key,caption,explanation,width in items:
            add_figure(doc,str(CHARTS/f'{key}.png'),caption,width=width,
                       source='Source: Data available for the official logback and signal day of the project; supplementary maps and lower CSV can be reproduced by code')
            add_text(doc,explanation)
        added=[e for e in list(body) if e not in original]
        for e in added:
            body.remove(e)
            target.addprevious(e)

    insert('1.3 ',[
      ('capital_risk_equal_weight','Cross-section of funds does not amount to risk-dissemination.',
       'The dots represent the share of the funds and the hollow diamond shape represents the contribution of risk at the same EWMA risk scale on the same date. Even with initial equivalents, fluctuations and correlations between nine equities and individual BTCs led to a deviation in the risk distribution from the distribution of funds. This section shows the meaning of fragmentation and should not be extrapolated to the historical average.',6.4),
      ('capital_risk_monthly_erc','Low-volatility classes require more capital. Price',
       'Risk parities shift allocation targets from capital shares to risk-taking, and therefore low volatility bonds or foreign exchange instruments may account for a larger proportion of funds. The EWMA matrix is used here to measure the two configurations in a uniform way, facilitating horizontal comparisons; the classic model would have used sample bands, so the share of risk in the diagram would not have to be equal to its original solvency target. The risk by target is not equal to risk by category.',6.4),
    ])
    insert('2.2 ',[
      ('research_path','Study route from configuration baseline to dynamic defense',
       'The study route brings back twelve strategies to their own problems: the risk model is a parallel comparison under the same Top10, and the budget and offensive mechanisms are a follow-up. It is therefore understandable why the more complex GARCH is not being used or that each addition of a module should be written up as a cost-free upgrade. The following empirical evidence gradually corresponds to this route.',6.65),
    ])
    insert('3.1 ',[]) if False else None
    insert('Part III',[]) if False else None
    # Position the tradeoff conclusion immediately before Part Three.
    part3=next(p for p in doc.paragraphs if 'Part three: Spirits.' in p.text and p.style.name=='Heading 1')
    original=set(body)
    add_figure(doc,str(CHARTS/'strategy_tradeoff.png'),'The benefits of the 12 official strategies of retreat and trade-offs',width=6.65)
    add_text(doc,'The scatterchart places the benefits in the same perspective as the risks: the final strategy is at a higher annualized yield position, but not the left-most low-evacuation area. The bubble slot suggests that there is still a need for active trading. The soundness and integrity of the asset, the ERC, retains the position of each of the lower retreats, and the choice of the spirit of defence means that the elasticity of the gains is preserved as a matter of priority rather than claiming that it is the best in all dimensions.')
    add_text(doc,'Recalculated calibration statement: This figure is derived from the official model implemented in the current environment. With the exception of a small variation in GARC, the key percentage indicators for the remaining 11 strategies are consistent with the original retention table; the three core strategies remain unchanged. GARCH recalculated its accumulated gains by about 0.37 percentage points and annualized fluctuations by about 0.14 percentage points. The formal table above retains the original preservation result and this environmental revaluation difference cannot be interpreted as an additional gain.',size=8.3,color='666666')
    for e in [e for e in list(body) if e not in original]:
        body.remove(e);part3._p.addprevious(e)
    insert('The final strategy is seven steps.',[
      ('construction_steps','Seven-step calculation and implementation chain of the final strategy',
       'The first four steps in the flowchart generate a core mix; the fifth decides on the ratio of candidates to funding for the current offensive; the sixth moves the theoretical mix of targets to a cut-off target, and the seventh creates a real hold. Budgets pre-empt the resolution of financial weights and make deals later than signals, which are key to understanding formulas and measuring returns. Details are given below in the same order.',6.65),
    ])
    insert('3.3 ',[
      ('attack_state','Net value.',
       'The upper layer is the net of three products, the middle layer is the offensive target and the corresponding breadth carried by the executed order, and the lower layer is the combination retreat and VIX crisis state. During the period around 2018 and part of 2022, there was a marked contraction in offensive targets; the trend resumed and then it increased. It explains how the rules are responsive, but the common change in the chart is not proof of the independent contribution of a certain article. The half-speed adjustment deviates the actual hold from the theoretical objective, so that the middle layer cannot be directly identified as the true proportion of funds in the independent offensive account.',6.65),
    ])
    snapshots=sorted(CHARTS.glob('risk_snapshot_*.csv'))
    risk_items=[]
    for path in snapshots:
        frame=pd.read_csv(path,index_col=0)
        category=frame['End-of-life risk contribution'].idxmax()
        risk=float(frame.loc[category,'End-of-life risk contribution'])
        capital=float(frame.loc[category,'Final funding weights'])
        explanation=(f'I\'m not sure what I\'m talking about.{category}the final risk contribution{risk:.2%}fund weights{capital:.2%}They\'re not the same.'
          +('This concentration suggests that a 30 per cent offensive capital ceiling is not a 30 per cent risk cap and that highly volatile assets may still dominate final portfolio risk.' if risk>.6 else '')+
          'The closeness of the blue core objective to the grey core solver indicates that the core budget has been converted into a risk contribution; the deep red final silo has passed through offensive superimposed and implementation buffers and is no longer aimed at a rigorous replication of the core budget.'
          'The three dates were fixed in advance at the end of 2017, in March 2020 and in the vicinity of October 2022, using the signal day availability matrix and not estimating the signal risk from the proceeds of the transaction.')
        risk_items.append((path.stem,'Synopsis of core risk budgets and final funding',explanation,6.5))
    insert('3.4 ',risk_items)
    insert('3.5 ',[
      ('annual_core_returns','Annual gains and phasing trade-offs for three products',
       'The annual graph shows that the offensive was not always profitable: the final strategy rose by 73.07 per cent in 2017, up from 33.50 per cent for the sound core; it fell by 9.12 per cent in 2018 and was deeper than the robust core - 4.89 per cent. The final strategy was -0.43 per cent in 2022, which is better than fixed offensives - 2.99 per cent; 31.52 per cent in 2024 and 19.94 per cent in 2025. Changes in relative location over different years indicate that the final scenario takes into account trend participation and contraction, and does not eliminate dependence on behaviour. The asterisk year is part of the year and cannot be compared to the same length.',6.65),
      ('market_state_returns','Means of beneficial participation in different market situations',
       'This figure is divided according to the share of proceeds over 63 days as of the same date. The 860-day increase group, with a net gain of 17.67 basis points per day for the final strategy, is higher than the 13.25 base point for the robust core; the 203-day fall group, with a final strategy of 2.08 basis points, with a fixed offensive of 4.47 basis points and a robust core of 2.42 basis points. Seismic team 1712 with a final strategy of 1.56 basis points. This group of ex post conditions averages are consistent with higher participation and lower vulnerability losses, but cannot separate the causal contribution of the modules. The state contains the same-day information, described only, and does not amount to a tradable timing gain, nor does it prove an independent projection of Alpha.',6.5),
    ])
    summary=pd.read_csv(CHARTS/'recovery_summary.csv')
    recovery_items=[]
    for rank in [1,2,3]:
        frame=summary[summary['Window'].eq(rank)]
        descriptions=[]
        for _,row in frame.iterrows():
            label=str(row['Policy']).split('·')[-1]
            repair=f"I don\'t think so.{int(row['Until the date of the transaction'])}One trading day back to the beginning." if pd.notna(row['Until the date of the transaction']) else 'Common window is not back to starting point'
            descriptions.append(f"{label}{repair}")
        explanation='；'.join(descriptions)+'I don\'t know. The window is determined by the three deepest retreats of the equal rights baseline, using the same starting and end dates. The repairs are not the maximum exit period per se for each strategy relative to the common starting point; the unrecovered window is the end of the observation and is not counted as zero.'
        recovery_items.append((f'recovery_path_{rank}','Dropping and repair process in common pressure windows',explanation,6.5))
    insert('4.2 ',recovery_items)
    # Keep main parts on a new page; do not leave the old standalone break
    # stranded before a newly inserted comparison figure.
    in_body=False
    for p in list(doc.paragraphs):
        if p.style.name=='Heading 1' and 'Part II' in p.text:
            in_body=True
        if in_body and not p.text.strip() and p._p.xpath('.//w:br[@w:type="page"]'):
            p._p.getparent().remove(p._p)
            continue
        if p.style.name=='Heading 1' and any(x in p.text for x in ['Part I','Part II','Part III','Part IV','Part V']):
            p.paragraph_format.page_break_before=True
    doc.save(REPORT)
    print(REPORT)


if __name__=='__main__':
    main()
